module jaro_winkler
@[export: 'jaro_winkler']
pub fn jaro_winkler(v &i64,n usize) f64{bad:= -1.0e300;if n<2||n>66{return bad};n1:=unsafe{v[0]};if n1<0||n1>32||1+n1>=n{return bad};p2:=1+int(n1);n2:=unsafe{v[p2]};if n2<0||n2>32||n!=p2+1+int(n2){return bad};for i in 0..int(n1){x:=unsafe{v[1+i]};if x<0||x>127{return bad}};for i in 0..int(n2){x:=unsafe{v[p2+1+i]};if x<0||x>127{return bad}};radius:=int(min(n1,n2)/2);mut u1:=[32]bool{};mut u2:=[32]bool{};mut a:=[32]i64{};mut b:=[32]i64{};mut ca:=0;mut cb:=0;for i in 0..int(n1){lo:=max(0,i-radius);hi:=min(i+radius+1,int(n2));for j in lo..hi{if !u2[j]&&unsafe{v[1+i]}==unsafe{v[p2+1+j]}{u2[j]=true;a[ca]=unsafe{v[1+i]};ca++;break}}};for i in 0..int(n2){lo:=max(0,i-radius);hi:=min(i+radius+1,int(n1));for j in lo..hi{if !u1[j]&&unsafe{v[p2+1+i]}==unsafe{v[1+j]}{u1[j]=true;b[cb]=unsafe{v[p2+1+i]};cb++;break}}};mut trans:=0;for i in 0..min(ca,cb){if a[i]!=b[i]{trans++}};trans/=2;mut jr:=f64(0);if ca>0{jr=(f64(ca)/f64(n1)+f64(ca)/f64(n2)+f64(ca-trans)/f64(ca))/3.0};mut prefix:=0;for prefix<4&&prefix<int(n1)&&prefix<int(n2)&&unsafe{v[1+prefix]}==unsafe{v[p2+1+prefix]}{prefix++};return jr+0.1*f64(prefix)*(1.0-jr)}
